 try{const savedBuilds=JSON.parse(localStorage.getItem(editorKey)||'{}'),oldAxe=savedBuilds['도끼방패'];if(oldAxe&&Array.isArray(oldAxe.core)&&oldAxe.core.join(',')==='흡혈검,덩굴 방패'&&(!oldAxe.recommended||oldAxe.recommended.length===0)&&Array.isArray(oldAxe.useful)&&oldAxe.useful.includes('구겸')&&oldAxe.useful.includes('정심회')){delete savedBuilds['도끼방패'];localStorage.setItem(editorKey,JSON.stringify(savedBuilds));}personalBuilds=validateBuilds(savedBuilds);Object.assign(D.weaponBuilds,personalBuilds);}catch(e){console.warn('개인 추천 기준을 불러오지 못했습니다.');}
