  function cutSummary(name,kind='option'){if(name==='시간 깃발')return '<div class="item-cut-meta"><span class="cut-value cut-min"><b>최소·종결</b><span>원하는 공격력형 또는 체력형 · 각 50%</span></span></div>';const item=P.itemMap[name],criteria=inputCriteria(name);if(!item)return '';const relevant=criteria.filter(c=>kind==='option'?c.kind==='effect':true);const suffix=key=>P.optionFields(name).find(x=>x[0]===key)?.[3]||'';const show=(c,value)=>c.key+(c.lowerBetter?' ≤ ':' ≥ ')+value+suffix(c.key);const minimum=relevant.map(c=>show(c,c.min));const terminal=criteria.filter(c=>c.kind==='effect'&&c.end!==null).map(c=>show(c,c.end));if(kind==='crafted'){for(const [key,label] of [['atk','공격력']]){const range=item[key];if(Array.isArray(range)&&range[0]!==range[1])terminal.push(label+' ≥ '+P.rollThresholds(...range).end);}}const fallback=kind==='option'?item.cut:item.statCut;return '<div class="item-cut-meta"><span class="cut-value cut-min"><b>사용 가능</b><span>'+esc(minimum.join(' · ')||fallback||'기준 확인 필요')+'</span></span><span class="cut-value cut-terminal"><b>종결</b><span>'+esc(terminal.join(' · ')||'기준 확인 필요')+'</span></span></div>';}
