 function cutPairs(text){return [...String(text||'').matchAll(/(\d+(?:\.\d+)?)[^\d\n]{0,18}\/[^\d\n]{0,18}(\d+(?:\.\d+)?)/g)].map(m=>[Number(m[1]),Number(m[2])]);}
