 function rollChance(low,high,target,lowerBetter=false){if(high<low)[low,high]=[high,low];const total=high-low+1,success=lowerBetter?Math.max(0,Math.min(high,Math.floor(target))-low+1):Math.max(0,high-Math.max(low,Math.ceil(target))+1);return total?success/total:0;}
