 function thresholdState(g){const criteria=inputCriteria(g?.name),values=criteria.map(c=>({c,v:currentInput(g,c.key)})),complete=values.length>0&&values.every(x=>x.v!==null),minOk=complete&&values.every(({c,v})=>c.lowerBetter?v<=c.min:v>=c.min),ends=values.filter(x=>x.c.end!==null),endOk=ends.length>0&&ends.every(({c,v})=>v!==null&&(c.lowerBetter?v<=c.end:v>=c.end));return {criteria,complete,minOk,endOk};}
  const weaponAttackExcluded=new Set(['검과 방패','망치방패','무거운 방패','창방','칼방','중기병']);const weaponStatsExcluded=new Set(['검과 방패','망치방패','무거운 방패','창방','칼방','중기병']);
  const milestoneList=[['one-valid','유효 옵션 1개'],['two-or-terminal','유효 옵션 2개 또는 종결 1개'],['core-useful','최우선 옵션 1개 · 최소 수치'],['core-terminal','최우선 옵션 1개 · 종결 수치'],['final','이번 판 최선 조합 종결']];
  function inputOptionCuts(name){const defs=P.optionFields(name),criteria=inputCriteria(name).filter(c=>c.kind==='effect');if(!defs.length||criteria.length!==defs.length)return null;return defs.map(([key,low,high])=>{const c=criteria.find(x=>x.key===key);return c?{key,low:Math.min(low,high),high:Math.max(low,high),min:c.min,end:c.end,lowerBetter:c.lowerBetter}:null;});}
