 function renderWeaponStats(){const w=P.unitMap[unit]?.weapon;$('dedicated-weapon-title').textContent=(w?.name||P.unitMap[unit]?.display||'전용무기')+' · 한 세트';const fields=w?['hp','atk'].map(k=>'<label>기본 '+(k==='hp'?'HP':'공격력')+' ('+w[k][0]+'~'+w[k][1]+')<input id="custom-weapon-'+k+'" type="number" inputmode="numeric" min="'+w[k][0]+'" max="'+w[k][1]+'" step="1" value="'+(customWeapon[k]??'')+'"></label>').join(''):'';$('custom-weapon-stats').innerHTML=!w?'<p class="muted">전용무기 기본 스탯 자료가 없습니다.</p>':weaponStatsIncluded()?fields:'<details class="weapon-stats-for-boss"><summary>보스 계산용 전무 스탯</summary><p class="muted">탱커 전무 스탯은 기댓값·종결 판정에 반영하지 않습니다. 보스 전투 계산용으로 입력합니다.</p><div class="fields">'+fields+'</div></details>';for(const k of ['hp','atk']){const input=$('custom-weapon-'+k);if(input){input.oninput=()=>{customWeapon[k]=input.value===''?null:Number(input.value);customWeaponCache[buildTarget+':'+unit]={...customWeapon};customInfo();};input.onchange=()=>{if(input.value!==''&&Number.isFinite(Number(input.value))){const n=Math.round(Number(input.value));if(n>=Number(input.min)&&n<=Number(input.max)){input.value=String(n);customWeapon[k]=n;customWeaponCache[buildTarget+':'+unit]={...customWeapon};customInfo();}}};}}}
