  function dedicatedResult(){const e=dedicatedExpected();if(!e.ready)return '<article class="result reforge-summary-card"><p>2번에서 이번 판 랜덤 옵션 8개를 선택하면 기댓값을 보여줍니다.</p><p class="muted">현재 '+pool.size+'/8 · 최우선 '+[...pool].filter(n=>poolMarks.get(n)==='core').length+'개 · 차선책 '+[...pool].filter(n=>poolMarks.get(n)==='alternative').length+'개</p></article>';const marked=e.effective.length,coreNames=e.core.map(o=>o.name).join(' · ')||'없음',alternativeNames=e.alternative.map(o=>o.name).join(' · ')||'없음',rows=[['유효 옵션 2개까지',e.twoUseful],['종결 옵션 2개까지',e.final]];return '<article class="result reforge-summary-card"><p class="muted">계산 대상 · 최우선 '+e.core.length+'개 ('+esc(coreNames)+') · 차선책 '+e.alternative.length+'개 ('+esc(alternativeNames)+')</p>'+(marked<2?'<p class="info">기댓값을 내려면 2개 이상을 최우선 또는 차선책으로 표시하세요. 선택된 옵션은 최우선·차선책 모두 계산에 포함됩니다.</p>':'')+'<div class="ev-rows">'+rows.map(([label,value])=>'<div class="ev-row"><span>'+label+'</span><strong>'+expectedLabel(value)+'</strong></div>').join('')+'</div>'+(e.finalReason?'<small class="muted">'+esc(e.finalReason)+'</small>':'')+'<small class="muted">유효 2개는 표시한 옵션에서 최소 컷을 넘는 경우입니다. 첫 유효 옵션은 고정하고 남은 칸에서 다른 유효 옵션을 찾습니다. 종결 2개는 최우선·차선책 중 어느 조합이든 종결 컷을 넘으면 인정하며, 첫 종결 옵션이 나오면 고정한 뒤 남은 7개에서 종결을 찾습니다. 표시한 모든 옵션의 효과 범위를 균등 확률로 계산합니다. 고정기 소모와 고정할 수 없는 기본 스탯은 이 옵션 횟수에서 분리했습니다.</small><details><summary>이번 판 최소·종결 수치</summary>'+e.effective.map(n=>'<p><strong>'+esc(n.name)+'</strong>'+cutSummary(n.name,'option')+'</p>').join('')+'</details></article>';}
