   function drawFields(){const g=gears[key][i],it=P.itemMap[g.name],co=kind==='crafted'?.5:boss?1:0,fields=row.querySelector('.gear-fields');if(!it){fields.innerHTML='';return;}if(boss){gears[key][i]=blankGear(g.name,1);fields.innerHTML='<p class="muted">最大치 적용 · HP +'+Math.round(it.hp[1]*co)+' / 공 +'+Math.round(it.atk[1]*co)+' · '+esc(P.options(g.name,1))+'</p>';return;}const stats=kind==='crafted'?['hp','atk'].filter(k=>it[k][0]!==it[k][1]):[];fields.innerHTML='<div class="fields">'+stats.map(k=>'<label>'+(k==='hp'?'기본 HP':'기본 공격력')+' ('+it[k][0]+'~'+it[k][1]+')<input data-stat="'+k+'" type="number" inputmode="numeric" min="'+it[k][0]+'" max="'+it[k][1]+'" step="1" value="'+(g.stats[k]??'')+'"></label>').join('')+P.optionFields(g.name).map(([name,a,b,suffix])=>'<label>'+esc(name)+' ('+a+'~'+b+(suffix||'%')+')<input data-effect="'+esc(name)+'" type="number" inputmode="numeric" min="'+Math.min(a,b)+'" max="'+Math.max(a,b)+'" step="1" value="'+(g.values[name]??'')+'"></label>').join('')+'</div><p class="gear-preview muted"></p>';const preview=()=>{let invalid=false;row.querySelectorAll('[data-stat]').forEach(inp=>{const value=inp.value===''?null:Number(inp.value);g.stats[inp.dataset.stat]=value;if(value!==null&&(value<Number(inp.min)||value>Number(inp.max)))invalid=true;});row.querySelectorAll('[data-effect]').forEach(inp=>{const value=inp.value===''?null:Number(inp.value);g.values[inp.dataset.effect]=value;const def=P.optionFields(g.name).find(d=>d[0]===inp.dataset.effect);if(value!==null&&(value<Math.min(def[1],def[2])||value>Math.max(def[1],def[2])))invalid=true;});const hp=kind==='crafted'?(g.stats.hp??'?'):0,atk=kind==='crafted'?(g.stats.atk??'?'):0;fields.querySelector('.gear-preview').textContent=(invalid?'범위를 확인하세요 · ':'')+'적용 스탯: HP +'+(hp==='?'?'입력 필요':Math.round(hp*co))+' · 공격력 +'+(atk==='?'?'입력 필요':Math.round(atk*co))+' · 효과 '+(Object.values(g.values).every(v=>v!==null&&v!==undefined)?'입력 완료':'입력 확인');};fields.querySelectorAll('input').forEach(inp=>{inp.oninput=()=>{preview();if(inputMode&&key==='custom')customInfo();else{renderPlayerGearSummary();updateBossSummary();invalidate();}};inp.onchange=()=>{if(inp.value!==''&&Number.isFinite(Number(inp.value))){const value=Math.round(Number(inp.value));if(value>=Number(inp.min)&&value<=Number(inp.max))inp.value=String(value);}preview();if(inputMode&&key==='custom')customInfo();else renderPlayerGearSummary();};});preview();}
