function renderPlayerGearInputs(key){renderGear(key==='primary'?'primary-gear-inputs':'secondary-gear-inputs',key,['normal','normal','crafted','crafted'],false,null,true);}
 function renderPlayerGearSummary(){for(const [key,id,titleId] of [['primary','primary-gear-summary','primary-title'],['secondary','secondary-gear-summary','secondary-title']]){const selector=$(key==='primary'?'boss-unit':'tank-unit'),unitData=P.unitMap[selector.value],list=gears[key]||[],prefix=key==='primary'?'':'tank-',weaponHp=$(prefix+'weapon-hp')?.value??'',weaponAtk=$(prefix+'weapon-atk')?.value??'',weapon='<p>전용무기 · HP +'+weaponHp+' / 공격력 +'+weaponAtk+'</p>';$(titleId).textContent=(unitData?.display||'병종')+'의 현재 장비';$(id).innerHTML=weapon+(list.some(g=>g.name)?list.map((g,i)=>g.name?'<p><strong>'+esc(g.name)+'</strong> · '+(i<2?'랜덤 옵션':'제련')+(i>=2?' · HP '+(g.stats.hp??'미입력')+' / 공격력 '+(g.stats.atk??'미입력'):'')+' · '+Object.entries(g.values||{}).map(([n,v])=>esc(n)+' '+(v??'미입력')).join(' · ')+'</p>':'').join(''):'<p>장비 옵션 없음 · 전용무기 기본 수치만 적용</p>');}}
 function gearPayload(key,size=4){const list=(gears[key]||[]).slice(0,size);const names=list.map(g=>g.name);if(new Set(names.filter(Boolean)).size!==names.filter(Boolean).length)throw Error('동일 장비를 중복 장착할 수 없습니다.');return {names,stats:list.map(g=>({...g.stats})),effects:list.map(g=>({...g.values})),rolls:list.map(()=>1)};}
