 function setupPanelCollapse(){document.querySelectorAll('.panel').forEach((panel,index)=>{if(panel.dataset.collapseReady)return;const title=panel.querySelector(':scope > h2, :scope > .section-head > h2');if(!title)return;panel.dataset.collapseReady='1';let header=title.parentElement;if(header===panel){header=document.createElement('div');header.className='panel-title-row';panel.insertBefore(header,title);header.append(title);}header.classList.add('panel-title-row');const body=document.createElement('div');body.className='panel-collapsible-content';[...panel.children].forEach(child=>{if(child!==header)body.append(child);});panel.append(body);const button=document.createElement('button');button.type='button';button.className='panel-collapse-button';button.setAttribute('aria-expanded','true');button.setAttribute('aria-label','내용 접기');button.textContent='⌄';header.append(button);button.onclick=()=>{const open=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!open));button.setAttribute('aria-label',open?'내용 펼치기':'내용 접기');button.textContent=open?'›':'⌄';body.hidden=open;};});}
 function updateBossSummary(){if(!$('boss-stat-summary'))return;try{$('boss-stat-summary').innerHTML=Object.entries(bossGear()).map(([id,g])=>{const e=D.opponents[id],z=P.loadout(e.ranged?'쇠뇌':'장검',e.level,g.names,1,{bossProfile:true,includeStats:true,slotKinds:g.slotKinds,effectValues:g.effectValues},{hp:e.hp,atk:e.atk});return '<p><strong>'+esc(e.name.replace('도적 두목','산적 두목'))+'</strong> 적용 HP '+z.hp+' · 공격력 '+Math.round(z.atk)+' · 공속 '+(e.speed??'자료 확인 필요')+' · 사거리 '+bossRange(id,g.names)+'</p>';}).join('');}catch(e){$('boss-stat-summary').textContent=e.message;}}
 function bossRage(){const out={};document.querySelectorAll('[data-boss-rage]').forEach(box=>{const [start,max]=[...box.querySelectorAll('input')].map(i=>i.value);if(start===''||max==='')throw Error('보스 시작 분노와 최대 분노를 함께 입력하세요.');out[box.dataset.bossRage]={start:Math.round(P.clamp(start,0,100)),max:Math.round(P.clamp(max,0,100))};});return out;}
