 const formations=[['two','병종 + 병종'],['unit-siege','병종 + 병기'],['two-siege','병종 2개 + 병기'],['unit','병종만'],['siege','병기만'],['hero','영웅 단독']];
 function setFormation(next){preset=next;const two=['two','two-siege'].includes(next),solo=next==='hero',machine=next==='siege',withSiege=['unit-siege','two-siege','siege'].includes(next);$('troop-one').hidden=machine;$('tank-controls').hidden=!two;$('primary-equipment').hidden=machine;$('secondary-equipment').hidden=machine||solo;$('siege-controls').hidden=!withSiege;$('include-hero').disabled=solo;if(solo)$('include-hero').checked=false;if(withSiege&&!$('siege-unit').value)$('siege-unit').value='쇠뇌차';if(!withSiege)$('siege-unit').value='';syncHeroes();heroVisibility();$('formation-cards').innerHTML=formations.map(([id,text])=>'<button data-preset="'+id+'" aria-pressed="'+(id===preset)+'">'+text+'</button>').join('');$('formation-cards').querySelectorAll('button').forEach(b=>b.onclick=()=>setFormation(b.dataset.preset));$('formation-note').textContent=solo?'선택한 기반 병종·레벨의 스탯과 전용무기에 영웅 추가 스탯을 더해 선택한 영웅만으로 검사합니다.':machine?'병기는 장비를 장착하지 않습니다. 보스 반사와 지정 피격을 검사합니다.':'최대 두 병종에 전용무기를 적용합니다. '+(two?'병종 1이 탱커, 병종 2가 딜러를 맡는 가정입니다.':'선택 병종이 탱커를 담당합니다.')+' 영웅 동반은 체크로 추가할 수 있습니다.';invalidate();}
