 function syncHeroes(){const units=preset==='hero'?equippable.map(u=>u.name):[...new Set([$('boss-unit').value,$('tank-unit').value])],eligible=D.heroes.filter(h=>units.includes(heroTroop(h)?.name)).sort((a,b)=>units.indexOf(heroTroop(a).name)-units.indexOf(heroTroop(b).name)),used=new Set();const available=Math.min(4,eligible.length);for(const o of $('hero-count').options)o.disabled=Number(o.value)>available;if(heroCount()>available)$('hero-count').value=String(Math.max(1,available));for(let i=1;i<=4;i++){const p=heroIds(i),old=$(p+'-name').value;$(p+'-unit').innerHTML=units.map(n=>'<option value="'+esc(n)+'">'+esc(P.unitMap[n].display)+'</option>').join('');$(p+'-unit').disabled=true;$(p+'-name').innerHTML=eligible.map(h=>'<option>'+esc(h.entity)+'</option>').join('');const picked=eligible.find(h=>h.entity===old&&!used.has(h.entity))||eligible.find(h=>!used.has(h.entity));if(picked){$(p+'-name').value=picked.entity;used.add(picked.entity);}if(old!==$(p+'-name').value||!units.includes($(p+'-unit').value))heroInfo(i);else {const h=eligible.find(h=>h.entity===old);if(h)$(p+'-unit').value=heroTroop(h).name;}}heroVisibility();}
