 function syncFormationHeroes(squads){const chosen=squads.filter(s=>s.hero).slice(0,4);if(!chosen.length)return;$('hero-count').value=String(chosen.length);chosen.forEach((s,i)=>{const p=heroIds(i+1),name=typeof s.hero==='string'?s.hero:$(p+'-name').value,options=[...$(p+'-name').options],option=options.find(o=>o.value===name||o.textContent===name);if(option&&$(p+'-name').value!==option.value){$(p+'-name').value=option.value;heroInfo(i+1);}const h=D.heroes.find(x=>x.entity===$(p+'-name').value),u=h&&heroTroop(h);if(u)$(p+'-unit').value=u.name;});heroVisibility();}
