function guide(cfg){const enc=D.encounters.find(e=>e.id===cfg.encounter)||selectedEncounter(),boss=cfg.bossIds?.[0]||enc.enemies.find(([id])=>D.opponents[id].kind==='boss')?.[0],steps=[],warnings=[];if(boss==='rat'){steps.push('탱커가 보스 시선을 잡고 원거리 딜러는 3칸 이상에서 공격하세요. 2칸 이내 타격은 전염병 중첩이 쌓입니다.','작성 중 공략의 시작 편제는 탱커 1명 + 딜러 8명이며, 무손실이 될 때까지 후속 딜러를 보강합니다. 이는 확정 최소 병력이 아닙니다.');}else if(boss==='gorilla'){steps.push('격노 후 강화 공격 2회와 주변 고정 피해를 고려해 탱커와 딜러를 떨어뜨리세요.','강화 공격 전에 처치할 화력을 확보하고, 탱커의 회복·보호막을 확인하세요.');}else if(boss==='goat'){steps.push('밀침·기절·대상 최대 HP 비례 광역 피해가 있으므로 한곳에 몰리지 않게 분산하세요.','충분한 화력이 확보된 뒤 도전하고, 밀려난 뒤의 후열 노출도 확인하세요.');}else if(boss==='leader'){steps.push('단일 타일 겹사를 피하고 탱커가 시선을 잡는 동안 딜러·병기는 사방으로 분산하세요.','공략의 참고 편제는 탱커 9명 + 쇠뇌차 36대, 5부대 분산입니다. 대장간14는 중요한 준비 단계지만 3.5% 관통의 최대치 조건은 직접 확인해야 합니다.');}else{steps.push('제자리 행동 가능한 선두 부대 → 탱커 → 후속 딜러 순서를 검토하세요.','멧돼지 기사 등 광역 적이 있는 구성에서는 겹사보다 분산을 우선 확인하세요.');}if(cfg.mode==='hero'){steps.splice(0,steps.length,'영웅 단독이므로 병사 탱커·후열 편제 없이 선택 영웅의 생존과 처치 능력을 검사합니다.',boss==='rat'?'쥐: 2칸 이내 공격은 전염병 중첩이 쌓입니다. 실제 영웅 사거리와 회복·보호막을 확인하세요.':boss==='leader'?'산적 두목: 혼자여도 누적 3연타를 버텨야 합니다. 실제 재능·회복·스킬을 입력하고, 영웅 고유 능력이 자동 적용된 것으로 보지 마세요.':boss==='goat'?'염소: 밀침·기절 중 생존과 대상 최대 HP 비례 피해를 버틸 회복·보호막이 필요합니다.':'강화 공격 또는 호위 병력을 영웅 혼자 감당하는 조건을 확인하세요.');}else if(P.unitMap[cfg.unit].group==='병기'){steps.splice(0,steps.length,'병기 단독 편제입니다. 병기에 장비를 붙이지 않고 사거리·관통·첫 피격·반사 피해를 검사합니다.','탱커가 없으므로 접근 전 처치가 가능한지 첫 공격 턴을 확인하세요. 보스 사거리 밖에서 자유롭게 공격한다고 자동 가정하지 않습니다.');}else {const front=P.unitMap[cfg.mode==='mixed'?cfg.tank:cfg.unit];if(front.role!=='tank')warnings.push(front.display+'가 현재 탱커를 맡습니다. 딜러 분류 병종이므로 집중 피격을 버틸 실제 생존 장비·능력을 확인하세요.');}if(enc.land===3){const rule={rat:'식량 · 쥐: 쇠뇌차 1부대 → 탱커 1부대 → 쇠뇌차 3부대',gorilla:'목재 · 고릴라: 탱커 1부대 → 쇠뇌차 4부대',goat:'석재 · 염소: 쇠뇌차 4부대 선행'}[boss];if(rule)steps.push('자원별 진입 기록 — '+rule);} for(const [id,g] of Object.entries(cfg.bossGear)){if(g.names.includes('피해 반사 갑옷'))warnings.push('보스 반사갑옷: 병기나 다타 딜러가 공격만으로 손실을 볼 수 있습니다. 반사 피해를 버티는지 먼저 검사하세요.');if(g.names.includes('유성추')&&id==='leader')warnings.push('산적 두목: 유성추 장착으로 사거리 6→7. 이동·어그로 변화는 수동 교전 조건에 반영해야 합니다.');if(g.names.includes('금 사슬갑옷'))warnings.push('보스 금 사슬갑옷: 여러 타격과 이월 피해를 고려해야 하며 본 모델은 피해 묶음 단위 근사입니다.');}if(cfg.mode==='hero'||cfg.supportHero)warnings.push('영웅 고유 능력 자동 적용이 불완전합니다. 영웅 단독 지옥2가 실전에서 가능하더라도 보정 없는 계산만으로 최소 컷을 확정할 수 없습니다.');for(const [u,names] of [[cfg.unit,cfg.names],[cfg.tank,cfg.mode==='mixed'?cfg.tankItems:['유성추']]])if(cfg.mode!=='hero'&&P.mandatory(u)&&!names.includes('유성추'))warnings.push(u+'의 현재 장비에 유성추가 없습니다. 사거리 보완 필수 기준을 충족하지 않은 입력입니다.');const confirmed=(D.bossRecords||[]).filter(r=>r.boss===boss&&(cfg.bossGear[boss]?.names||[]).includes(r.equipment));for(const r of confirmed)steps.unshift('사용자 실전 확인: '+r.equipment+' 염소는 대장간'+r.forgeLevel+' 쇠뇌차 '+r.count+'대(2부대)로 무손실 처치. 이 기록은 계산 결과와 별도이며, 전역 최소 병력을 뜻하지 않습니다.');return {steps,warnings,record:enc.formation};}
 function practicalAdvice(cfg,base){const tips=[],enc=D.encounters.find(e=>e.id===cfg.encounter)||selectedEncounter(),boss=cfg.bossIds?.[0]||enc.enemies.find(([id])=>D.opponents[id].kind==='boss')?.[0],front=P.unitMap[cfg.mode==='mixed'?cfg.tank:cfg.unit],back=P.unitMap[cfg.unit];
  if(cfg.mode==='mixed'&&!cfg.formationMembers?.length){const total=cfg.count+cfg.tankCount;let best={cfg,result:base};for(let n=1;n<total;n++){const test={...cfg,tankCount:n,count:total-n},r=P.combat(test,test.names,1);if((r.cleared&&!best.result.cleared)||r.cleared===best.result.cleared&&(r.casualties<best.result.casualties||r.casualties===best.result.casualties&&r.enemyRemaining<best.result.enemyRemaining))best={cfg:test,result:r};}if(best.cfg!==cfg&&(best.result.casualties<base.casualties||best.result.cleared&&!base.cleared))tips.push('편성 변경: '+front.display+' '+cfg.tankCount+'명 + '+back.display+' '+cfg.count+'명 → '+front.display+' '+best.cfg.tankCount+'명 + '+back.display+' '+best.cfg.count+'명. 같은 총 병력에서 모델상 손실 '+base.casualties+' → '+best.result.casualties+'명'+(best.result.cleared?'으로 클리어.':'으로 감소.'));}
  if(!base.success){const groups=[[cfg.unit,'effectValues',cfg.names],...(cfg.mode==='mixed'?[[cfg.tank,'tankEffects',cfg.tankItems]]:[])];outer:for(const [unit,key,names] of groups)for(let i=0;i<names.length;i++)for(const [label,a,b] of P.optionFields(names[i])){if(/확률|배율|회피|기절/.test(label)||['군기','황월','옥패','현목 영락','모래시계','시간 깃발','백참도','명광 갑옷'].includes(names[i]))continue;const current=Math.round(cfg[key]?.[i]?.[label]??b),direction=b>=a?1:-1;for(let v=current+direction;direction>0?v<=b:v>=b;v+=direction){const effects=(cfg[key]||[]).map(e=>({...e}));if(!effects[i])continue;effects[i][label]=v;const test={...cfg,[key]:effects,heroes:cfg.heroes?.map(h=>h.unit===unit?{...h,effects}:h)},r=P.combat(test,test.names,1);if(r.success||r.casualties<base.casualties||r.cleared&&!base.cleared){tips.push('옵션 보강: '+P.unitMap[unit].display+'의 '+names[i]+' · '+label+' '+current+' → '+v+(label==='타격 상한'?' 이하':' 이상')+'. 다른 입력을 유지한 모델 비교에서 '+(r.success?'무손실 통과':r.cleared?'클리어 확인':'손실 '+r.casualties+'명으로 감소')+'.');break outer;}}}
   if(tips.length<2&&cfg.mode!=='hero'&&back.group!=='병기'&&cfg.level<6){const test={...cfg,level:cfg.level+1},r=P.combat(test,test.names,1);if(r.success||r.casualties<base.casualties||r.cleared&&!base.cleared)tips.push('병종 강화: '+back.display+' Lv.'+cfg.level+' → Lv.'+test.level+'. 같은 장비·인원으로 모델상 '+(r.success?'무손실 통과':r.cleared?'클리어 확인':'손실 '+r.casualties+'명으로 감소')+'.');}}
  if(cfg.mode==='mixed')tips.push(boss==='leader'?'투입·배치: '+front.display+' 탱커 부대를 먼저 진입시키고 '+back.display+' 부대는 다른 방향에 분산하세요. 한 칸 겹사는 피하세요.':'투입 순서: '+front.display+' 탱커 부대 → '+back.display+' 딜러 부대. '+(boss==='rat'?'딜러는 보스와 3칸 이상 거리를 유지하세요.':boss==='gorilla'?'탱커와 딜러를 떨어뜨려 격노 광역 피해를 줄이세요.':'탱커와 딜러가 한곳에 몰리지 않게 배치하세요.'));
  else if(back.group==='병기'&&boss==='goat')tips.push('편성·진입: 쇠뇌차만으로 분산 진입을 검토하세요. 월아도·금 사슬갑옷 염소는 대장간14, 쇠뇌차18대(2부대) 무손실 실전 기록이 있습니다. 해당 장비에서 확인한 사례입니다.');
  else tips.push(cfg.mode==='hero'?'영웅 편성: 탱커를 맡길 영웅을 앞에 두고 원거리 영웅은 뒤에 배치하세요. 영웅 능력의 실제 효과를 함께 확인하세요.':'투입·배치: 탱커가 시선을 잡은 뒤 후속 화력을 투입하세요. 광역 보스에게는 부대를 한곳에 겹치지 마세요.');
  if(base.success)tips.unshift('현재 입력은 모델상 무손실입니다. 장비 옵션을 더 올리기 전에 아래 최소 병력 컷을 확인하세요.');
  if(tips.length<2&&!base.success)tips.push('현재 장비·인원에서 단일 옵션 보강이나 같은 총 병력 재편만으로 뚜렷한 개선을 확인하지 못했습니다. 확인되지 않은 숫자를 최소 컷으로 제시하지 않습니다.');
  return tips.slice(0,3);}
 function methods(cfg){const plans=[{name:'현재 입력 조건',cfg:{...cfg}},{name:'탱커 고정·후열 분산 가정',cfg:{...cfg,dealerExposure:0,siegeExposure:0,heroExposure:0,heroes:cfg.heroes?.map(h=>({...h,exposure:0}))}},{name:'후열 25% 노출 대비',cfg:{...cfg,dealerExposure:25,siegeExposure:cfg.siege||P.unitMap[cfg.unit].group==='병기'?25:0,heroExposure:25,heroes:cfg.heroes?.map(h=>({...h,exposure:25}))}}];const seen=new Set();return plans.filter(p=>{const key=[p.cfg.dealerExposure,p.cfg.siegeExposure,p.cfg.heroExposure].join('|');if(seen.has(key))return false;seen.add(key);return true;});}
 function army(cfg){return (cfg.mode==='hero'?0:cfg.count)+(cfg.mode==='mixed'?cfg.tankCount:0)+(cfg.siege?cfg.siegeCount:0);}
  function candidatesForCounts(cfg){const a=cfg.mode==='hero'?0:cfg.count,b=cfg.mode==='mixed'?cfg.tankCount:0,c=cfg.siege?cfg.siegeCount:0,all=[];for(let x=a?1:0;x<=(a||0);x++)for(let y=b?1:0;y<=(b||0);y++)for(let z=c?1:0;z<=(c||0);z++){if(x+y+z>45)continue;const next={...cfg,count:cfg.mode==='hero'?1:(a?x:cfg.count),tankCount:b?y:cfg.tankCount,siegeCount:c?z:cfg.siegeCount};if(cfg.formationMembers?.length){const remaining=new Map();if(cfg.mode==='mixed'){remaining.set(cfg.unit,next.count);remaining.set(cfg.tank,next.tankCount);}else if(cfg.mode!=='hero')remaining.set(cfg.unit,next.count);if(cfg.siege)remaining.set(cfg.siege,next.siegeCount);const filtered=[];for(const m of cfg.formationMembers){if(m.kind==='hero'){filtered.push(m);continue;}const key=m.kind==='siege'?(cfg.siege||m.unit):m.unit,left=remaining.get(key)||0;if(left>0){filtered.push(m);remaining.set(key,left-1);}}next.formationMembers=filtered;}if(army(next)<=45)all.push(next);}return all.sort((x,y)=>army(x)-army(y));}
  function fmt(value){const n=Number(value);return Number.isFinite(n)?n.toFixed(1):'—';}
  function lineupHtml(c){if(!c.formationMembers?.length)return '';const groups=new Map();for(const m of c.formationMembers){const k=Number(m.squad)||0;groups.set(k,[...(groups.get(k)||[]),m]);}return '<details><summary>계산한 부대 순서 확인</summary>'+[...groups.entries()].sort((a,b)=>a[0]-b[0]).map(([i,ms])=>{const counts={};for(const m of ms){const label=m.kind==='siege'?'쇠뇌차':m.kind==='hero'?(m.name||'영웅'):(P.unitMap[m.unit]?.display||m.unit);counts[label]=(counts[label]||0)+1;}return '<p><strong>'+(i+1)+'부대</strong> · '+Object.entries(counts).map(([n,v])=>esc(n)+(v>1?' '+v+'명':'')).join(' + ')+'</p>';}).join('')+'</details>';}
  function gearLine(title,u,names,stats,effects,weaponHp,weaponAtk){const items=(names||[]).map((name,i)=>{if(!name)return '';const opts=Object.entries(effects?.[i]||{}).filter(([,v])=>Number(v)!==0).map(([n,v])=>esc(n)+' '+Math.round(v)).join(' · ');const base=i>=2?'제련 기본스탯 50% · HP +'+Math.round((stats?.[i]?.hp||0)/2)+' / 공격 +'+Math.round((stats?.[i]?.atk||0)/2):'랜덤 기본스탯 미적용';return '<li>'+(i<2?'랜덤':'제련')+' · '+esc(name)+' · '+base+(opts?' · '+opts:'')+'</li>';}).filter(Boolean).join('');return '<section><strong>'+esc(title)+' · '+esc(P.unitMap[u]?.display||u)+'</strong><p>전용무기 기본 HP +'+Math.round(Number(weaponHp)||0)+' / 공격 +'+Math.round(Number(weaponAtk)||0)+'</p>'+(items?'<ul>'+items+'</ul>':'<p>장비 없음 · 전용무기 기본 수치만 적용</p>')+'</section>';}
  function gearAudit(c){const parts=[];if(c.mode==='hero'){for(const h of c.heroes||[])parts.push(gearLine('영웅 '+h.name,h.unit,h.items,h.stats,h.effects,h.weaponHp,h.weaponAtk));}else if(P.unitMap[c.unit]?.group!=='병기'){parts.push(gearLine(c.mode==='mixed'?'병종 2':'병종',c.unit,c.names,c.itemStats,c.effectValues,c.weaponHp,c.weaponAtk));}if(c.mode==='mixed')parts.push(gearLine('병종 1',c.tank,c.tankItems,c.tankStats,c.tankEffects,c.tankWeaponHp,c.tankWeaponAtk));if(P.unitMap[c.unit]?.group==='병기')parts.push('<section><strong>병기 · '+esc(P.unitMap[c.unit].display)+'</strong><p>병기는 장비를 장착하지 않습니다.</p></section>');if(c.supportHero)for(const h of (c.heroes||[]))parts.push(gearLine('영웅 '+h.name,h.unit,h.items,h.stats,h.effects,h.weaponHp,h.weaponAtk));return '<details class="result-audit"><summary>계산에 반영한 장비·옵션 확인</summary>'+parts.join('')+(c.siege?'<p><strong>쇠뇌차</strong> · 장비 미착용 · 관통 '+c.pierce+'%</p>':'')+'</details>';}
  function result(r,c,title){const losses=r.losses.map(x=>esc(x.unit)+' '+x.dead+'/'+x.total).join(' · ');return '<article class="result"><h3>'+esc(title)+'</h3><p class="stat">'+(r.success?'계산 모델상 무손실 통과':r.cleared?'계산 모델상 클리어 · 손실 있음':'현재 조건으로 클리어 미확인')+' · '+r.turns+'턴</p><p>손실 추정 '+r.casualties+'개체 · '+losses+'<br>적 남은 HP '+fmt(r.enemyRemaining)+' · 앞선 부대 HP '+fmt(r.frontEnd)+(r.siegeEnd!==null?' · 쇠뇌차 HP '+fmt(r.siegeEnd):'')+(r.heroEnd!==null?' · 영웅 HP '+fmt(r.heroEnd):'')+'</p><p>조건: 후열 피격 '+c.dealerExposure+'%, 병기 피격 '+c.siegeExposure+'%, 아군 첫 공격 '+c.allyStart+'턴. 실전 클리어 보증이 아닌 입력값 기반 예측입니다.</p>'+gearAudit(c)+lineupHtml(c)+'<details><summary>계산 범위와 미반영 효과</summary><p>'+[...new Set(r.warnings)].map(esc).join('<br>')+'<br>손실은 개체 체력·순차 교체 기준의 추정이며 실제 격자 좌표와 무작위 광역 피격은 완전히 재현하지 않습니다.</p></details></article>';}const yieldUI=()=>new Promise(r=>setTimeout(r,0));
  async function optionCuts(cfg,currentToken){const answer=[],sources=cfg.mode==='mixed'?[['병종 2','effectValues','names',cfg.unit],['병종 1','tankEffects','tankItems',cfg.tank]]:cfg.mode==='hero'?[]:[['병종','effectValues','names',cfg.unit]];for(const [title,key,namesKey,unit] of sources){const list=(cfg[namesKey]||[]).map((name,i)=>({name,values:cfg[key]?.[i]||{}}));for(let i=0;i<list.length;i++){const g=list[i];if(!g.name)continue;for(const [label,a,b] of P.optionFields(g.name)){if(/확률|배율|회피|기절/.test(label)||['시간 깃발','군기','현목 영락','황월','백참도','명광 갑옷','모래시계','옥패','분심계','태양 갑옷'].includes(g.name))continue;const value=Math.round(g.values[label]),direction=b>=a?1:-1;if(!Number.isFinite(value))continue;for(let cutValue=a;direction>0?cutValue<=value:cutValue>=value;cutValue+=direction){if(currentToken!==token)return [];const test={...cfg,[key]:(cfg[key]||[]).map(v=>({...v}))};if(!test[key][i])continue;test[key][i][label]=cutValue;test.heroes=cfg.heroes?.map(h=>h.unit===unit?{...h,effects:test[key]}:h);if(P.combat(test,cfg.names,1).success){answer.push({title,name:g.name,label,value:test[key][i][label],others:value});break;}}}await yieldUI();}}return answer;}
 function missingPlayerGear(){const entered=v=>v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v));for(const key of ['primary','secondary'])for(const g of (gears[key]||[]).filter(x=>x.name)){if(P.optionFields(g.name).some(([n])=>!entered(g.values&&g.values[n])))return g.name+' 옵션 수치를 보스 탭 장비 입력란에 입력하세요.';const i=(gears[key]||[]).indexOf(g);if(i>=2&&['hp','atk'].some(k=>P.itemMap[g.name][k][0]!==P.itemMap[g.name][k][1]&&!entered(g.stats&&g.stats[k])))return g.name+' 기본 스탯을 보스 탭 장비 입력란에 입력하세요.';}return ''; }
 async function analyze(){const currentToken=++token;try{const missing=missingPlayerGear();if(missing)throw Error(missing);const cfg=config();if(!cfg.bossIds?.length)throw Error('보스를 하나 이상 체크하세요.');if(window.NTASquads){cfg.squads=window.NTASquads.read();const unsupported=window.NTASquads.unsupported();if(unsupported)throw Error(unsupported);if(!window.NTASquads.validate())throw Error('편성한 부대에는 병사·병기 또는 영웅을 배치하고, 영웅은 부대당 한 명만 선택하세요.');}if(army(cfg)>45)throw Error('총 병력·병기를 45개체 이내로 입력하세요.');$('cancel-search').hidden=false;const note=guide(cfg),tested=methods(cfg).map(p=>({...p,result:P.combat(p.cfg,p.cfg.names,1,{trace:true})})),current=tested[0];note.steps=practicalAdvice(cfg,current.result);$('boss-results').innerHTML='<article class="result" id="boss-guide"><h3>추천 진행 방법</h3><ol>'+note.steps.map(s=>'<li>'+esc(s)+'</li>').join('')+'</ol>'+(note.warnings.length?'<details><summary>계산 전 확인 사항</summary>'+note.warnings.map(s=>'<p>'+esc(s)+'</p>').join('')+'</details>':'')+'<details><summary>자료의 편제·실측 기록</summary><p>'+esc(note.record)+'</p></details><p class="muted">아래 판정은 먼저 보낸 부대와 장비 입력을 사용한 모델 예측입니다.</p></article>'+result(current.result,current.cfg,'현재 입력한 편성의 예상 결과');let cut=null,count=0;const variants=candidatesForCounts(current.cfg);for(const c of variants){if(currentToken!==token)return;const r=P.combat(c,c.names,1);count++;if(r.success){cut={cfg:c,result:r};break;}if(count%30===0){$('search-status').textContent='현재 장비·부대순서 유지 · 인원 조합 '+count+'/'+variants.length+' 검사';await yieldUI();}}if(currentToken!==token)return;if(cut){const c=cut.cfg;$('boss-results').innerHTML+='<article class="result" id="boss-cut"><h3>현재 편제에서 줄여 본 최소 컷</h3><p class="stat">모델상 무손실 통과 · 총 병사·병기 '+army(c)+'개체</p><p>현재 장비와 부대 순서를 유지하고 각 부대의 뒤쪽 개체부터 줄여 처음 통과한 값입니다. 다른 순서·진형의 전체 최소값은 아닙니다.</p>'+lineupHtml(c)+'</article>';const cuts=await optionCuts(c,currentToken);if(currentToken!==token)return;$('boss-results').innerHTML+='<details><summary>장비 옵션별 조건부 최소 컷</summary><p>현재 편제를 고정해 각 옵션만 따로 낮춰본 값입니다. 각 최소값을 동시에 적용하면 실패할 수 있습니다.</p>'+cuts.map(x=>'<p>'+esc(x.title)+' · '+esc(x.name)+' · '+esc(x.label)+' <strong>'+Math.round(x.value)+'</strong></p>').join('')+(!cuts.length?'<p>현재 입력에는 역산할 수 있는 직접 반영 옵션이 없습니다.</p>':'')+'</details>';}else $('boss-results').innerHTML+='<article class="result" id="boss-cut"><h3>무손실 최소 컷</h3><strong>현재 장비와 부대 순서를 유지한 범위에서 무손실 조합을 찾지 못했습니다.</strong><p>게임에서 클리어할 수 없다는 뜻은 아닙니다. 실제 좌표·영웅 능력·광역 대상은 모델과 다를 수 있습니다. 부대 카드에서 인원이나 순서를 바꿔 다시 확인하세요.</p></article>';if(tested.length>1)$('boss-results').innerHTML+='<details><summary>후열이 더 노출될 때의 참고 비교</summary>'+tested.slice(1).map(x=>result(x.result,x.cfg,x.name)).join('')+'</details>';$('boss-results').innerHTML+='<details><summary>현재 편성의 턴별 결과</summary><div class="table-wrap"><table><tr><th>턴</th><th>적 HP</th><th>앞선 부대 HP</th><th>후열 HP</th></tr>'+current.result.events.map(x=>'<tr><td>'+x.turn+'</td><td>'+fmt(x.enemyHP)+'</td><td>'+fmt(x.frontHP)+'</td><td>'+fmt(x.dealerHP)+'</td></tr>').join('')+'</table></div></details>';$('search-status').textContent='검사 완료 · 입력 장비·실제 편성 순서 기준 · '+count+'개 인원 조합 검사';}catch(e){$('boss-results').textContent=e.message;}finally{if(currentToken===token){$('cancel-search').hidden=true;arrangeResults();}}}
  function compactHero(){const box=$('hero-controls'),fields=box.querySelector('.fields'),details=document.createElement('details');details.className='hero-details';details.innerHTML='<summary>상세 설정</summary><div class="fields"></div>';const target=details.querySelector('.fields');for(const label of [...fields.children])if(!label.querySelector('#hero-name,#hero-level'))target.appendChild(label);for(const e of [...box.children])if(e!==fields)details.appendChild(e);box.appendChild(details);}
 function compactPage(){for(const el of document.querySelectorAll('.panel > p.muted,.panel > p.callout'))if(el.textContent.length>70){const d=document.createElement('details');d.className='compact-help';d.innerHTML='<summary>설명 보기</summary>';el.replaceWith(d);d.appendChild(el);}const policy=document.querySelector('[data-policy]').closest('.info'),settings=$('page-boss').querySelector('details:has(#turns)'),button=$('analyze-boss'),d=document.createElement('details');d.className='compact-policy';d.innerHTML='<summary id="policy-summary">공격 정책 · 1단계</summary>';policy.replaceWith(d);d.appendChild(policy);button.before(d,settings);$('page-boss').querySelectorAll('[data-policy]').forEach(e=>e.addEventListener('change',()=>{$('policy-summary').textContent='공격 정책 · 1단계 · '+document.querySelectorAll('[data-policy]:checked').length+'개 선택';}));}
 function formationSummary(){if(!$('formation-summary')||!$('boss-unit')?.value)return;const pieces=[];if(preset!=='hero'&&preset!=='siege')pieces.push(P.unitMap[$('boss-unit').value].display+' '+Math.round(Number($('count').value))+'명');if(['two','two-siege'].includes(preset))pieces.push(P.unitMap[$('tank-unit').value].display+' '+Math.round(Number($('tank-count').value))+'명');if(['siege','unit-siege','two-siege'].includes(preset)&&$('siege-unit').value)pieces.push($('siege-unit').value+' '+Math.round(Number($('siege-count').value))+'대');if(preset==='hero'||$('include-hero').checked)pieces.push('영웅 '+heroCount()+'명');$('formation-summary').textContent=pieces.join(' + ');}
 function arrangeResults(){const box=$('boss-results'),guide=$('boss-guide'),cut=$('boss-cut');if(!guide)return;const loss=[...box.children].find(e=>e!==guide&&e!==cut&&e.classList.contains('result'));if(loss)box.prepend(loss);if(cut&&loss)loss.after(cut);if(guide)(cut||loss)?.after(guide);}
 function sourceInfo(){ $('source-content').innerHTML='<h3>최근 NTA 정리 반영</h3><p>2026-10-21 사용자 통합안의 병종별 코어·추천·쓸만함 기준을 반영했습니다. 병종 역할과 조건을 함께 보고, 탱커 기본 세트와 기존 예외 규칙을 유지합니다.</p><h3>자료 적용 순서</h3><p>사용자 정정 → 사용자 제공 NTA 정리 → 사용자 공략 기록. 보스 본 장비 최대 기본 스탯, 두목 제련 기본HP·공격력50%·효과최대100%는 이번 사용자 정정을 우선 적용합니다.</p><h3>최신 V4 검증 대기</h3><p>황월의 확률 발동/보호막 변경, 건곤도의 상성 공격력 보정, 보호막·회피·Miss에서 분노가 차지 않는다는 예외는 최신 V4에서도 검증 대기입니다. 추천표의 평가와 확정 게임 규칙을 구분합니다.</p><h3>병종별 추천 근거</h3>'+equippable.map(u=>{const b=P.buildOpinion(u.name);return '<details><summary>'+esc(u.display)+' · '+esc(u.weapon?.name||u.name)+'</summary><p>코어: '+b.core.map(esc).join(' + ')+'<br>추천: '+b.recommended.map(esc).join(' + ')+'<br>쓸만함·유틸: '+b.useful.map(esc).join(' + ')+'<br>두더지: '+(b.mole||[]).map(esc).join(' + ')+(b.roleNote?'<br>역할 기준: '+esc(b.roleNote):'')+'</p></details>';}).join('')+'<h3>이전 장비 세팅</h3>'+D.history.map(h=>'<article class="result"><strong>'+esc(h.title)+'</strong><p>'+h.items.map(esc).join(' + ')+'</p><p>'+esc(h.note)+'</p><a href="chatgpt-conversation://'+h.thread+'">장비 분석 대화</a></article>').join('')+'<h3>보스·자원지 기록</h3>'+D.encounters.map(e=>'<p><strong>'+esc(e.difficulty)+'</strong> — '+esc(e.formation)+'</p>').join('')+'<h3>장비별 추천 옵션과 원문</h3>'+D.equipment.map(i=>'<details><summary>'+esc(i.name)+'</summary><p>'+esc(i.description)+'</p><p>일반 추천 옵션: '+esc(P.optionCutText(i.name))+'<br>기본 스탯 참고: '+esc(i.statCut)+'</p></details>').join('');}
 function renderGuide(){
  const host=$('guide-content');if(!host)return;
  host.innerHTML='<details class="guide-part guide-checklist-part"><summary>✅ 초보자 체크리스트<span class="guide-part-hint">첫날 · 둘째날 · 셋째날</span></summary><div class="guide-checklist-body"><div class="guide-checklist-head"><p>진행한 항목을 체크하면 이 브라우저에 저장됩니다.</p><button type="button" class="guide-check-reset">체크 초기화</button></div><div class="guide-checkgrid"><fieldset><legend>첫날 목표</legend><label><input type="checkbox" data-guide-check="day1-0">도감 확인</label><label><input type="checkbox" data-guide-check="day1-1">달팽이 그리기</label><label><input type="checkbox" data-guide-check="day1-2">거점 14레벨</label><label><input type="checkbox" data-guide-check="day1-3">대장간 14레벨(전용무기 제련)</label><label><input type="checkbox" data-guide-check="day1-4">영지 100개+</label><label><input type="checkbox" data-guide-check="day1-5">팀 게임이면 대사관 8</label></fieldset><fieldset><legend>둘째날 목표</legend><label><input type="checkbox" data-guide-check="day2-0">거점 18레벨</label><label><input type="checkbox" data-guide-check="day2-1">2번째 전용무기 제작</label><label><input type="checkbox" data-guide-check="day2-2">팀 게임이면 대사관 13</label></fieldset><fieldset><legend>셋째날 목표</legend><label><input type="checkbox" data-guide-check="day3-0">거점 20레벨</label><label><input type="checkbox" data-guide-check="day3-1">6렙 병력 최대한 영끌</label><label><input type="checkbox" data-guide-check="day3-2">전무 제련(임시옵션, 여름 중 완성)</label><label><input type="checkbox" data-guide-check="day3-3">영지 190 이하 유지(안전 할 때 까지 절대 넘지 말 것)</label></fieldset></div><h4>🎯 반드시 숙지해야 할 핵심 사항</h4></div></details><details class="guide-part"><summary>기본편<span class="guide-part-hint">초반 성장 · 파밍 · 장비</span></summary><iframe class="guide-frame" src="guide/basic.html" loading="lazy" title="초보자를 위한 공략 기본편"></iframe></details><details class="guide-part"><summary>전투편<span class="guide-part-hint">공타 · 전투 준비 · 거점 전투</span></summary><iframe class="guide-frame" src="guide/combat.html" loading="lazy" title="초보자를 위한 전투 공략"></iframe></details><details class="guide-part"><summary>장비<span class="guide-part-hint">역할별 구성 · 피해 계산 · 차선책</span></summary><iframe class="guide-frame" src="guide/equipment.html" loading="lazy" title="병종 역할에 맞는 장비 구성"></iframe></details>';
  host.querySelectorAll('.guide-part').forEach(part=>{part.open=false;});
  const checks=[...host.querySelectorAll('[data-guide-check]')];
  for(const c of checks){c.checked=localStorage.getItem('nta-guide-check-'+c.dataset.guideCheck)==='1';c.addEventListener('change',()=>localStorage.setItem('nta-guide-check-'+c.dataset.guideCheck,c.checked?'1':'0'));}
  host.querySelector('.guide-check-reset')?.addEventListener('click',()=>{for(const c of checks){c.checked=false;localStorage.removeItem('nta-guide-check-'+c.dataset.guideCheck);}});
 }

 function exportSession(){return {unit,unitFilter,candidateFilter,buildTarget,pool:[...pool],poolMarks:[...poolMarks],candidates:[...candidates],custom,customWeapon,customWeaponCache,gears,unitGearCache:{...unitGearCache,['primary:'+$('boss-unit').value]:gears.primary,['secondary:'+$('tank-unit').value]:gears.secondary},selectedBosses:[...selectedBosses],bossGearOpen:[...bossGearOpen],variants:Object.fromEntries(equippable.map(u=>[u.name,P.buildOpinion(u.name).variantKey]))};}
 function restoreSession(s){if(!s||!P.unitMap[s.unit])return;unit=s.unit;unitFilter=['전체','방패병','창병','궁병','기병'].includes(s.unitFilter)?s.unitFilter:'전체';candidateFilter=['전체','추천','선택한 장비'].includes(s.candidateFilter)?s.candidateFilter:'전체';buildTarget=s.buildTarget==='secondary'?'secondary':'primary';pool=new Set((s.pool||[]).filter(n=>P.itemMap[n]).slice(0,8));poolMarks=new Map((s.poolMarks||[]).filter(([n,v])=>pool.has(n)&&['pool','core','alternative'].includes(v)));candidates=new Set((s.candidates||[]).filter(n=>P.itemMap[n]).slice(0,8));customWeapon=s.customWeapon||{hp:null,atk:null};customWeaponCache=s.customWeaponCache||{};Object.assign(gears,s.gears||{});Object.assign(unitGearCache,s.unitGearCache||{});custom=(gears.custom||[]).map(g=>g.name||'');selectedBosses=new Set((s.selectedBosses||[]).filter(n=>['rat','goat','gorilla','leader'].includes(n)));bossGearOpen=new Map(s.bossGearOpen||[]);for(const [n,v] of Object.entries(s.variants||{}))P.setRecommendationVariant(n,v);for(const id of ['boss-unit','tank-unit'])$(id).dataset.prev='';chooseUnit('primary');chooseUnit('secondary');renderUnits();unitSummary();chips();recommend();encounterInfo();renderPlayerGearSummary();}
 document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>showPage(b.dataset.page));$('clear-pool').onclick=()=>{pool.clear();poolMarks.clear();chips();revealReforgePanel();};$('suggest-candidates').onclick=()=>{candidateFilter=candidateFilter==='추천'?'전체':'추천';chips();};$('clear-candidates').onclick=()=>{candidates.clear();chips();revealReforgePanel();};$('make-recommendations').onclick=recommend;$('edit-player-gear').onclick=()=>showPage('units');
 for(const id of ['boss-unit','tank-unit','hero-unit'])$(id).innerHTML=equippable.map(u=>'<option value="'+esc(u.name)+'">'+esc(u.display)+'</option>').join('');$('boss-unit').value='무거운 방패';$('tank-unit').value='강화 쇠뇌';$('hero-name').innerHTML=D.heroes.map(h=>'<option>'+esc(h.entity)+'</option>').join('');$('boss-unit').onchange=()=>chooseUnit('primary');$('tank-unit').onchange=()=>chooseUnit('secondary');initHeroes();$('include-hero').onchange=()=>{heroVisibility();invalidate();};$('analyze-boss').onclick=analyze;$('cancel-search').onclick=()=>{invalidate();$('search-status').textContent='검사를 중지했습니다.';};document.querySelectorAll('#page-boss input,#page-boss select').forEach(e=>e.addEventListener('input',e.type==='number'?integerInput:invalidate));
 compactPage();setupPanelCollapse();editorInit();renderUnits();unitSummary();chips();recommend();chooseUnit('primary');chooseUnit('secondary');syncHeroes();encounterInfo();setFormation('two');sourceInfo();renderGuide();return {showPage,setFormation,invalidate,exportSession,restoreSession,refreshGearSummary:renderPlayerGearSummary,heroChoices:unit=>D.heroes.filter(h=>heroTroop(h)?.name===unit).map(h=>h.entity),syncFormationHeroes};
